from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
a=s.index('function g3RoundNumberQuestionData(stage){')
b=s.index('function g3UnitNumberQuestion(',a)
s=s[:a]+"const G3_ROUND_VARIANTS=[\n [\"tAdd\",\"tSub\",\"hAdd\",\"hSub\"],\n [\"tMul\",\"tDiv\",\"hMul\",\"hDiv\"],\n [\"hChain\",\"mixed\",\"dualMul\",\"missing\"]\n];\nfunction g3RoundNumberQuestionData(stage,slot=null){\n const d=Math.max(0,Math.min(2,Number(stage)||0)),variants=G3_ROUND_VARIANTS[d];\n const type=slot===null?g6RandomFrom(variants):variants[((slot%variants.length)+variants.length)%variants.length];\n let text,answer,ex,audit={type:\"roundNumbers\",variant:type};\n if(type===\"tAdd\"||type===\"tSub\"||type===\"hAdd\"||type===\"hSub\"){\n  const factor=type[0]===\"t\"?10:100,au=type.endsWith(\"Add\")?ri(1,7):ri(3,9);\n  const bu=type.endsWith(\"Add\")?ri(1,9-au):ri(1,au-1),a=au*factor,b=bu*factor,plus=type.endsWith(\"Add\");\n  answer=plus?a+b:a-b;\n  text=\"Вычисли: <b>\"+a+(plus?\" + \":\" − \")+b+\"</b> = ?\";\n  const unit=factor===10?\"дес.\":\"сот.\";\n  ex=au+\" \"+unit+(plus?\" + \":\" − \")+bu+\" \"+unit+\" = \"+(plus?au+bu:au-bu)+\" \"+unit+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,b,answer};\n }else if(type===\"tMul\"||type===\"hMul\"){\n  const factor=type===\"tMul\"?10:100,units=ri(1,factor===10?9:4),k=ri(2,Math.min(9,Math.floor(9/units))),a=units*factor;\n  answer=a*k;text=\"Умножь: <b>\"+a+\" · \"+k+\"</b> = ?\";\n  ex=units+\" \"+(factor===10?\"дес.\":\"сот.\")+\" · \"+k+\" = \"+(units*k)+\" \"+(factor===10?\"дес.\":\"сот.\")+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,k,answer};\n }else if(type===\"tDiv\"||type===\"hDiv\"){\n  const factor=type===\"tDiv\"?10:100,k=ri(2,9),qUnits=ri(1,Math.floor(9/k)),a=qUnits*k*factor;\n  answer=qUnits*factor;text=\"Раздели: <b>\"+a+\" : \"+k+\"</b> = ?\";\n  ex=(qUnits*k)+\" \"+(factor===10?\"дес.\":\"сот.\")+\" : \"+k+\" = \"+qUnits+\" \"+(factor===10?\"дес.\":\"сот.\")+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,k,answer};\n }else if(type===\"hChain\"){\n  const au=ri(3,8),bu=ri(1,au-1),cu=ri(1,Math.min(2,au-bu)),a=au*100,b=bu*100,c=cu*100;\n  answer=a-b+c;text=\"Вычисли по порядку: <b>\"+a+\" − \"+b+\" + \"+c+\"</b> = ?\";\n  ex=\"Сначала \"+a+\" − \"+b+\" = \"+(a-b)+\".<br>Затем \"+(a-b)+\" + \"+c+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,b,c,answer};\n }else if(type===\"mixed\"){\n  const a=ri(3,8)*100,b=ri(2,9)*10,c=ri(1,Math.min(3,b/10))*10;\n  answer=a+b-c;text=\"Вычисли: <b>\"+a+\" + \"+b+\" − \"+c+\"</b> = ?\";\n  ex=\"Сначала \"+a+\" + \"+b+\" = \"+(a+b)+\".<br>Затем \"+(a+b)+\" − \"+c+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,b,c,answer};\n }else if(type===\"dualMul\"){\n  const a=ri(2,5)*10,k=ri(2,4),b=ri(2,5)*10,h=ri(2,4);\n  answer=a*k+b*h;\n  text=\"Найди сумму двух произведений: <b>\"+a+\" · \"+k+\" + \"+b+\" · \"+h+\"</b> = ?\";\n  ex=a+\" · \"+k+\" = \"+(a*k)+\"; \"+b+\" · \"+h+\" = \"+(b*h)+\".<br>\"+(a*k)+\" + \"+(b*h)+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,b,k,h,answer};\n }else{\n  const au=ri(3,8),bu=ri(1,au-1),a=au*100,b=bu*100,c=ri(1,6)*10;\n  answer=a-b-c;\n  text=\"Найди неизвестное число: <b>□ + \"+c+\" = \"+a+\" − \"+b+\"</b>\";\n  ex=\"Правая часть: \"+a+\" − \"+b+\" = \"+(a-b)+\".<br>Неизвестное число: \"+(a-b)+\" − \"+c+\" = <b>\"+answer+\"</b>.\";\n  audit={...audit,a,b,c,answer};\n }\n return {text,answer,ex,audit};\n}\n"+s[b:]
a=s.index(' if(raw==="round_numbers"){')
b=s.index(' if(raw==="zero_one"){',a)
s=s[:a]+" if(raw===\"round_numbers\"){\n  const live=stageOverride===null&&blockSession?.kind===\"g3quiz\"&&blockSession.key===\"g3:round_numbers\";\n  const data=g3RoundNumberQuestionData(d,live?blockSession.done:null);\n  return g6NumberInputQuestion(data.text,data.answer,data.ex,\"g3:round_numbers:\"+d+\":\"+data.audit.variant+\":\"+Object.entries(data.audit).filter(([key])=>key!==\"type\"&&key!==\"variant\"&&key!==\"answer\").map(([,v])=>v).join(\":\"),{inputHint:\"Введи целое число.\",audit:{...data.audit,answer:rational(data.answer,1)}});\n }\n"+s[b:]
assert s.count('function g3RoundNumberQuestionData(')==1
assert s.count('const G3_ROUND_VARIANTS=')==1
p.write_text(s,encoding='utf-8')
print('round numbers patch applied:',len(s))
